function fold(s) {
  return (s || '')
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/['’.]/g, '')
    .replace(/&/g, ' and ')
    .replace(/[^a-z0-9\s]/gi, ' ')
    .toLowerCase()
    .replace(/\s+/g, ' ')
    .trim();
}

const MASCOTS = [...new Set(CBB_TEAMS.map(t => fold(t.mascot)).filter(Boolean))]
  .sort((a, b) => b.length - a.length);

